# Notebook to publish predictions table to online store for low-latency serving
import json
import urllib.request
import urllib.parse

catalog    = dbutils.widgets.get("catalog")
db_schema  = dbutils.widgets.get("db_schema")
prefix     = dbutils.widgets.get("prefix")
store_name = dbutils.widgets.get("store_name")

cs = f"{catalog}.{db_schema}"
pred_table = f"{cs}.airqpredfdfb59"
online_table_name = f"{prefix}_airqpredfdfb59"

print(f"Publishing {pred_table} to online store {store_name}")

# Get Databricks auth info from context
ctx = dbutils.notebook.entry_point.getDbutils().notebook().getContext()
token = ctx.apiToken().get()
host = ctx.apiUrl().get()
print(f"Host: {host}")

status = "not_started"

# Approach 1: REST API with proper URL encoding
try:
    # URL-encode the entire table name for path safety
    # For the feature store API, we need to use %2E for dots
    table_encoded = pred_table.replace('.', '%2E')
    url = f"{host}/api/2.0/feature-store/tables/{table_encoded}/publish"
    print(f"REST API URL: {url}")

    payload = json.dumps({
        'publish_spec': {
            'online_store': store_name,
            'online_table_name': online_table_name,
            'publish_mode': 'SNAPSHOT'
        }
    }).encode('utf-8')

    req = urllib.request.Request(
        url,
        data=payload,
        headers={
            'Authorization': f'Bearer {token}',
            'Content-Type': 'application/json'
        },
        method='POST'
    )

    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            body = resp.read().decode('utf-8')
            print(f"REST API success: {body[:300]}")
            status = "published_via_rest_encoded"
    except urllib.error.HTTPError as e:
        body = e.read().decode('utf-8')
        print(f"REST API error {e.code}: {body[:500]}")

except Exception as e:
    print(f"REST API exception: {e}")

# Approach 2: Create online table via UC REST API (newer endpoint)
if "published" not in status:
    try:
        url2 = f"{host}/api/2.0/online-tables"
        payload2 = json.dumps({
            'name': f"{cs}.{pred_table.split('.')[-1]}_online",
            'spec': {
                'source_table_full_name': pred_table,
                'primary_key_columns': ['date'],
                'run_triggered': {}
            }
        }).encode('utf-8')

        req2 = urllib.request.Request(
            url2,
            data=payload2,
            headers={
                'Authorization': f'Bearer {token}',
                'Content-Type': 'application/json'
            },
            method='POST'
        )

        try:
            with urllib.request.urlopen(req2, timeout=60) as resp:
                body = resp.read().decode('utf-8')
                print(f"Online table API success: {body[:300]}")
                status = "created_online_table"
        except urllib.error.HTTPError as e:
            body = e.read().decode('utf-8')
            print(f"Online table API {e.code}: {body[:300]}")
    except Exception as e:
        print(f"Online table API exception: {e}")

# Approach 3: Use databricks SDK (if available)
if "published" not in status:
    try:
        from databricks.sdk import WorkspaceClient
        w = WorkspaceClient()
        from databricks.sdk.service.catalog import (
            OnlineTable, OnlineTableSpec, OnlineTableSpecTriggeredSchedulingPolicy
        )
        ot = w.online_tables.create(
            table=OnlineTable(
                name=f"{cs}.airqpredfdfb59_online",
                spec=OnlineTableSpec(
                    source_table_full_name=pred_table,
                    primary_key_columns=["date"],
                    run_triggered=OnlineTableSpecTriggeredSchedulingPolicy(),
                )
            )
        )
        print(f"SDK online table: {ot.name}")
        status = "created_online_table_sdk"
    except Exception as e:
        print(f"SDK online table error: {e}")

print(f"Final status: {status}")
result = {"status": status, "pred_table": pred_table, "online_store": store_name}
print(json.dumps(result))
dbutils.notebook.exit(json.dumps(result))
